import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
let mode = args[0]
let workers = 0
if ((mode === 'waves' || mode === 'explain') && args.length === 1) {
  // ok
} else if (mode === 'pack' && args.length === 2) {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const depsOf = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) depUses.push(x)
    if (!depsOf.has(w[1])) depsOf.set(w[1], new Set())
    for (const d of w.slice(2)) depsOf.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const x of depUses) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort()
const deps = new Map(names.map((k) => [k, [...(depsOf.get(k) || [])].sort()]))
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
for (const k of names) deps.get(k).sort(cmp)
names.sort(cmp)

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const d of deps.get(u)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d))
        cyc.push(d)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const calc = (u) => {
  if (finish.has(u)) return
  let s = 0
  let dp = 0
  for (const d of deps.get(u)) {
    calc(d)
    s = Math.max(s, finish.get(d))
    dp = Math.max(dp, depth.get(d) + 1)
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, dp)
}
names.forEach(calc)
const total = names.reduce((m, k) => Math.max(m, finish.get(k)), 0)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((w, i) => (out += `wave ${i}: ${w.join(' ')}\n`))
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const dependents = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of deps.get(k)) dependents.get(d).push(k)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0
    for (const v of dependents.get(u)) m = Math.max(m, pr(v))
    prio.set(u, m + cost.get(u))
    return prio.get(u)
  }
  names.forEach(pr)
  const done = new Map() // name -> finish
  const remaining = new Set(names)
  const freeAt = new Array(workers).fill(0)
  const ran = Array.from({ length: workers }, () => [])
  let t = 0
  for (;;) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      let best = null
      for (const k of remaining) {
        if (!deps.get(k).every((d) => done.has(d) && done.get(d) <= t)) continue
        if (best === null || pr(k) > pr(best) || (pr(k) === pr(best) && k < best)) best = k
      }
      if (best === null) break
      remaining.delete(best)
      const f = t + cost.get(best)
      done.set(best, f)
      freeAt[wi] = f
      ran[wi].push(`${best}@${t}-${f}`)
    }
    const next = freeAt.filter((f) => f > t)
    if (!next.length) break
    t = Math.min(...next)
  }
  ran.forEach((r, i) => (out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`))
  out += `makespan ${total}\n`
}
process.stdout.write(out)
EOF
